pub fn validate_email(email: &str) -> bool {
    if email.is_empty() || email.trim().is_empty() {
        return false;
    }

    if email.contains(' ') || email.contains('\n') || email.contains('\0') {
        return false;
    }

    let parts: Vec<&str> = email.split('@').collect();
    if parts.len() != 2 {
        return false;
    }

    let local = parts[0];
    let domain = parts[1];

    if local.is_empty() || domain.is_empty() {
        return false;
    }

    if local.starts_with('.') || local.ends_with('.') || local.contains("..") {
        return false;
    }

    for c in local.chars() {
        if !c.is_alphanumeric() && c != '.' && c != '_' && c != '-' && c != '+' {
            return false;
        }
    }

    if domain.starts_with('.') || domain.ends_with('.') || domain.starts_with('-') || domain.ends_with('-') {
        return false;
    }

    if domain.contains(' ') || domain.contains('\n') || domain.contains('\0') {
        return false;
    }

    let domain_parts: Vec<&str> = domain.split('.').collect();
    if domain_parts.len() < 2 {
        return false;
    }

    for part in &domain_parts {
        if part.is_empty() {
            return false;
        }
        for c in part.chars() {
            if !c.is_alphanumeric() && c != '-' {
                return false;
            }
        }
    }

    true
}

